<script setup lang="ts">
import { computed,nextTick,onMounted,onUnmounted,ref,watch } from 'vue'
import {localDatabase} from '../lib/local-database'
import { lotteries,formatBall,formatTicket,type LotteryId,type Ticket } from '../lib/picker'
import { addObservations,addUnverifiedObservations,evaluate,loadObservations,saveObservations,validateDraw,observationStatus,type LotteryObservation,type OfficialIssue } from '../lib/lottery-observation'
const props=defineProps<{active:boolean}>()
const emit=defineEmits<{notice:[message:string];change:[count:number]}>()
const rows=ref<LotteryObservation[]>([]),storageError=ref(''),filter=ref('all'),busy=ref(false),dialog=ref(false),game=ref<LotteryId>('ssq'),tickets=ref<Ticket[]>([]),issues=ref<OfficialIssue[]>([]),issue=ref(''),message=ref(''),saving=ref(false),loadingIssues=ref(false),detail=ref<string|null>(null)
const dialogElement=ref<HTMLElement|null>(null)
let returnFocus:HTMLElement|null=null
function trapDialog(event:KeyboardEvent){if(!dialog.value)return;if(event.key==='Escape'&&!saving.value){event.preventDefault();dialog.value=false;return}if(event.key!=='Tab')return;const elements=Array.from(dialogElement.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),a[href]')||[]);const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
watch(dialog,async value=>{if(value){returnFocus=document.activeElement as HTMLElement;await nextTick();dialogElement.value?.querySelector<HTMLInputElement>('input')?.focus();document.addEventListener('keydown',trapDialog)}else {document.removeEventListener('keydown',trapDialog);returnFocus?.focus()}})
onUnmounted(()=>document.removeEventListener('keydown',trapDialog))
let openGeneration=0
const issueTouched=ref(false),note=ref('')
const names=Object.fromEntries(lotteries.map(l=>[l.id,l.name]))
const labels={pending:'待开奖',checking:'待核对',won:'已命中',lost:'未命中',unsupported:'暂不支持核奖'}
const status=(r:LotteryObservation)=>!r.result&&r.issueVerification==='unverified'?'待核实期号':labels[observationStatus(r)]
const visible=computed(()=>rows.value.filter(r=>filter.value==='all'||observationStatus(r)===filter.value))
let writes=Promise.resolve()
function persist(change:(rows:LotteryObservation[])=>LotteryObservation[]){const operation=writes.catch(()=>{}).then(async()=>{if(storageError.value)throw Error(storageError.value);const next=change(rows.value);await localDatabase.persist(storage=>saveObservations(storage,next));rows.value=next;emit('change',next.length)});writes=operation;return operation}
async function request(path:string){const response=await fetch(`/api/lottery-observations/${path}`,{signal:AbortSignal.timeout(12000)});let data;try{data=await response.json()}catch{throw Error('当前服务未提供观察接口，请确认使用本项目 Node 服务')}if(!response.ok)throw Error(data.error||'官方查询失败');return data}
async function fetchIssues(){const generation=openGeneration;loadingIssues.value=true;try{const data=await request(`issues?id=${game.value}${issue.value?'&issue='+encodeURIComponent(issue.value):''}`);if(generation!==openGeneration)return;issues.value=data.issues||[];message.value=data.message||'';if(!issueTouched.value)issue.value=issues.value[0]?.issue||data.defaultIssue?.issue||issue.value}catch(e){if(generation===openGeneration)message.value=(e as Error).message}finally{if(generation===openGeneration)loadingIssues.value=false}}
function open(id:LotteryId,values:Ticket[]){openGeneration++;game.value=id;tickets.value=values.map(t=>({primary:[...t.primary],secondary:[...t.secondary]}));issue.value='';note.value='';issueTouched.value=false;issues.value=[];message.value='';dialog.value=true;void fetchIssues()}
defineExpose({open})
async function add(){if(saving.value)return;saving.value=true;try{if(storageError.value)throw Error(storageError.value);if(!/^\d{5,7}$/.test(issue.value))throw Error('请填写官方原始期号（5 至 7 位数字）');const confirmed=issues.value.find(i=>i.issue===issue.value);let confirmedPending=false
 if(confirmed)confirmedPending=true
 else {const result=await request(`result?id=${game.value}&issue=${encodeURIComponent(issue.value)}`);if(result.status==='published')throw Error('此期已经开奖，不能新建观察；请填写待开奖期号');}
 const before=rows.value.length;await persist(current=>confirmedPending?addObservations(current,confirmed!,tickets.value,Date.now(),note.value):addUnverifiedObservations(current,game.value,issue.value,tickets.value,Date.now(),note.value));const count=rows.value.length-before;dialog.value=false;emit('notice',count?`已添加 ${count} 组彩票观察${confirmed?'':'（期号待核实）'}`:'这些号码已在该期观察中')
 }catch(e){message.value=(e as Error).message}finally{saving.value=false}}
async function refresh(){if(busy.value||storageError.value)return;busy.value=true;let failed=0;try{for(const r of [...rows.value]){try{const data=await request(`result?id=${r.id}&issue=${encodeURIComponent(r.issue)}`);const current=rows.value.find(x=>x.key===r.key);if(!current)continue;let next:LotteryObservation;if(data.status==='published'){const result=validateDraw(r.id,r.issue,data.result);next={...current,result,drawTime:result.drawTime,issueVerification:'verified',error:undefined}}else {next={...current,error:data.message||'官方完整结果尚未发布'};if(data.status==='source-error')failed++}await persist(current=>current.map(x=>x.key===r.key?{...x,...next}:x))}catch(e){failed++;const current=rows.value.find(x=>x.key===r.key);if(current){try{await persist(current=>current.map(x=>x.key===r.key?{...x,error:(e as Error).message}:x))}catch(err){storageError.value=(err as Error).message;break}}}}if(failed)emit('notice',`${failed} 组暂未更新，已保留上次完整结果`)}finally{busy.value=false}}
async function remove(r:LotteryObservation){if(!confirm(`移除${names[r.id]}第 ${r.issue} 期这组观察？`))return;try{await persist(current=>current.filter(x=>x.key!==r.key))}catch(e){emit('notice',(e as Error).message)}}
onMounted(()=>{try{rows.value=loadObservations(localDatabase.storage);emit('change',rows.value.length);void refresh()}catch(e){storageError.value=(e as Error).message;emit('notice',storageError.value)}})
watch(()=>props.active,active=>{if(active)void refresh()})
</script>
<template>
 <section v-show="active" class="lottery-observations" aria-label="我的彩票观察">
  <div class="lottery-observation-heading"><div><h2>我的彩票观察 <small>{{rows.length}}</small></h2><p>只观察指定一期，进入页面自动核对，也可以手动刷新。</p></div><button :disabled="busy||!!storageError" @click="refresh">{{busy?'正在核对…':'刷新结果'}}</button></div>
  <p v-if="storageError" role="alert" class="lottery-observation-warning">{{storageError}}</p>
  <div class="lottery-observation-filters" aria-label="筛选"><button v-for="[value,label] in [['all','全部'],['pending','待开奖'],['checking','待核对'],['won','已命中'],['lost','未命中']]" :key="value" :aria-pressed="filter===value" @click="filter=value">{{label}}</button></div>
  <div v-if="!visible.length" class="lottery-observation-empty"><h3>{{rows.length?'暂无符合条件的观察':'还没有彩票观察'}}</h3><p>在选号页将单组号码或全部 10 组加入观察，默认使用当前期号，也可修改后保存。</p></div>
  <article v-for="r in visible" :key="r.key" class="lottery-observation-card">
   <div class="lottery-observation-heading"><strong>{{names[r.id]}} · 第 {{r.issue}} 期</strong><span class="lottery-observation-state">{{status(r)}}<template v-if="r.result&&evaluate(r.id,r.ticket,r.result).status==='won'"> · {{evaluate(r.id,r.ticket,r.result).label}}</template></span></div>
   <div class="lottery-observation-balls"><span v-for="(n,i) in r.ticket.primary" :key="'p'+i" :class="{hit:r.result&&evaluate(r.id,r.ticket,r.result).primaryHits.includes(i)}">{{formatBall(r.id,n)}}</span><span v-for="(n,i) in r.ticket.secondary" :key="'s'+i" class="secondary" :class="{hit:r.result&&evaluate(r.id,r.ticket,r.result).secondaryHits.includes(i)}">{{formatBall(r.id,n)}}</span></div>
   <p v-if="r.note" class="observation-memo"><span>备注</span>{{r.note}}</p>
   <p>{{r.drawTime?'开奖日期：'+r.drawTime:'开奖日期与销售截止尚未核实，请查看官方公告'}}</p><p v-if="r.error" class="lottery-observation-warning">{{r.error}}<template v-if="r.result">；以下为上次完整结果</template></p>
   <div class="lottery-observation-actions"><button :aria-expanded="detail===r.key" @click="detail=detail===r.key?null:r.key">{{detail===r.key?'收起详情':'核对详情'}}</button><button @click="remove(r)">移除</button></div>
   <div v-if="detail===r.key" class="lottery-observation-detail"><template v-if="r.result"><p>官方开奖号码：{{formatTicket(r.id,r.result)}}<template v-if="r.id==='qlc'">（后区为特别号）</template></p><p>{{evaluate(r.id,r.ticket,r.result).label}} · {{r.id==='dlt'?'适用第 26014 期起基本投注规则':'按已核实的 2026 年基本玩法规则核对'}}</p><p>更新时间：{{new Date(r.result.updatedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+'（北京时间）'}}</p></template><p v-else>尚无本期完整官方结果，不据此判断未命中。</p><a :href="r.result?.source||r.source" target="_blank" rel="noopener noreferrer">官方数据来源</a><p>{{['pl3','fc3d','pl5','qxc'].includes(r.id)?'按对应位置核对；只支持当前生成的直选／单选玩法。':'按各区号码集合核对；只显示基本投注奖级。'}} 不计算奖金，不连续追期。</p></div>
  </article>
  <p class="lottery-observation-footnote">仅保存模拟号码，不表示已购票。核对结果以实际票据和官方公告为准。</p>
 </section>
 <Teleport to="body"><div v-if="dialog" class="lottery-observation-backdrop" @click.self="!saving&&(dialog=false)" @keydown.esc="!saving&&(dialog=false)"><section ref="dialogElement" class="lottery-observation-dialog" role="dialog" aria-modal="true" aria-labelledby="lottery-observation-title" tabindex="-1"><div class="lottery-observation-heading"><h2 id="lottery-observation-title">加入{{names[game]}}观察</h2><button :disabled="saving" aria-label="关闭" @click="dialog=false">×</button></div><p>{{tickets.length}} 组号码 · 指定一期，不连续追期</p><div class="lottery-observation-preview"><p v-for="(t,i) in tickets" :key="i">{{formatTicket(game,t)}}</p></div><label for="lottery-observation-issue">观察期号</label><input id="lottery-observation-issue" v-model.trim="issue" inputmode="numeric" maxlength="7" placeholder="正在获取默认期号，可手动修改" :disabled="saving" @input="issueTouched=true" @keyup.enter="add"><p v-if="loadingIssues">正在查询官方期次…</p><p v-if="message" role="status" class="lottery-observation-hint">{{message}}</p><p v-if="issues.find(i=>i.issue===issue)">预计开奖：{{issues.find(i=>i.issue===issue)?.drawTime}} · 截止：{{issues.find(i=>i.issue===issue)?.cutoff}}</p><label for="lottery-observation-note">备注 <span class="note-optional">选填 · {{note.length}}/300</span></label><textarea id="lottery-observation-note" v-model="note" maxlength="300" rows="3" :disabled="saving" :placeholder="tickets.length>1?'例如：本周生日号，这批号码使用同一条备注':'例如：生日组合，留意这一期的结果'"></textarea><p>仅保存模拟号码，不表示已购票。已公布开奖结果的期次不能新增。</p><div class="lottery-observation-actions"><button :disabled="saving||loadingIssues" @click="fetchIssues">刷新默认期号</button><button :disabled="saving||!issue||!!storageError" @click="add">{{saving?'正在校验…':'保存本期观察'}}</button></div><p v-if="storageError" role="alert">{{storageError}}</p></section></div></Teleport>
</template>
<style scoped>
.lottery-observations{max-width:1100px;margin:0 auto;padding:24px 0;color:#24262c}.lottery-observation-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}.lottery-observation-heading h2{margin:0;font-size:22px}.lottery-observation-heading small{font-size:14px;color:#777}.lottery-observation-heading p,.lottery-observation-card p,.lottery-observation-dialog p{line-height:1.65;color:#70727b;font-size:13px}.lottery-observation-filters,.lottery-observation-actions{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.lottery-observations button,.lottery-observation-dialog button{border:1px solid #dedfe5;background:#fffefa;border-radius:9px;padding:9px 14px;color:#393b45;cursor:pointer;font:inherit;font-size:13px}.lottery-observations button:disabled,.lottery-observation-dialog button:disabled{opacity:.45;cursor:wait}.lottery-observation-filters button[aria-pressed=true]{background:#566548;color:white}.lottery-observation-card{border:1px solid #e5e5ea;background:#fffefa;border-radius:16px;padding:20px;margin:14px 0}.lottery-observation-state{font-size:12px;background:#edf0e6;border-radius:20px;padding:6px 10px}.lottery-observation-balls{display:flex;gap:7px;flex-wrap:wrap;margin-top:18px}.lottery-observation-balls span{display:grid;place-items:center;width:33px;height:33px;border-radius:50%;background:#f7eeee;color:#b05959;font-size:13px;font-weight:600}.lottery-observation-balls .secondary{background:#eef3fb;color:#527ab7}.lottery-observation-balls .hit{background:#bd4a4a;color:#fff}.lottery-observation-balls .secondary.hit{background:#4277ba}.lottery-observation-hint{font-size:12px;line-height:1.7;color:#8b806f}.lottery-observation-warning{color:#936629!important;background:#fff6e8;border-radius:8px;padding:10px}.lottery-observation-empty{padding:60px 20px;text-align:center;border:1px dashed #d7d7df;border-radius:16px;color:#777}.lottery-observation-empty h3{color:#444;font-size:17px}.lottery-observation-empty p,.lottery-observation-footnote{font-size:13px;color:#82838a;line-height:1.6}.lottery-observation-detail{border-top:1px solid #eee;padding-top:8px}.lottery-observation-detail a{font-size:13px;color:#566548}.lottery-observation-backdrop{position:fixed;inset:0;background:#17192388;z-index:1000;display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(4px)}.lottery-observation-dialog{background:#fffefa;border-radius:20px;padding:26px;max-width:540px;width:100%;max-height:90dvh;overflow:auto;box-shadow:0 24px 80px #0003;color:#24262c}.lottery-observation-dialog label{display:block;font-size:14px;margin:18px 0 8px}.lottery-observation-dialog input{box-sizing:border-box;width:100%;font:inherit;padding:12px;border:1px solid #d6d5df;border-radius:8px}.lottery-observation-preview{max-height:140px;overflow:auto;background:#f4f2e9;border-radius:10px;padding:8px 14px;font-variant-numeric:tabular-nums}.lottery-observation-preview p{margin:4px 0;color:#43434d}.lottery-observation-dialog .lottery-observation-actions button:last-child{background:var(--red,#a84a3b);color:#fff}@media(max-width:600px){.lottery-observations{padding:12px 0}.lottery-observation-card{padding:16px}.lottery-observation-dialog{padding:20px}.lottery-observation-backdrop{padding:12px}.lottery-observation-heading h2{font-size:19px}}
</style>
